mapper.select:
select a.action_id as actionId, a.action_type as actionType, a.effective_date as effectiveDate, a.business_status as businessStatus, a.operator_name as operatorName, o.status as deliveryStatus, o.remote_task_id as taskId from sys_hr_lifecycle_action a left join sys_hr_sign_event_outbox o on o.action_id = a.action_id and o.event_version = a.version where a.employee_id = #{employeeId}
and a.action_type = 'REGULARIZATION_CONFIRMED' and a.action_type in ('RENEWAL_DECISION','RENEWAL_CONFIRMED','RENEWAL_DECLINED') and 1 = 0
order by a.action_id desc limit 20

select action_type from sys_hr_lifecycle_action
where employee_id = #{employeeId} and source_type = 'HR_RENEWAL' and source_business_id = #{cycleKey}
  and action_type in ('RENEWAL_DECISION','RENEWAL_CONFIRMED','RENEWAL_DECLINED')
